import {MfeEvent} from '../../interfaces';
import {addMfeEventListener, dispatchMfeEvent, isEventCached, isEventNameValid} from '../mfe-communication';

describe('mfe-communication tests', () => {
  it('should test isEventNameValid', () => {
    expect(2).toBe(2);

    expect(isEventNameValid('a.b')).toBe(true);
    expect(isEventNameValid('a.b.c')).toBe(true);
    expect(isEventNameValid('a.b.c.d')).toBe(true);
    expect(isEventNameValid('one.two')).toBe(true);
    expect(isEventNameValid('one.two.three')).toBe(true);
    expect(isEventNameValid('one.two.three.four')).toBe(true);
    expect(isEventNameValid('!a.b')).toBe(true);
    expect(isEventNameValid('!a.b.c')).toBe(true);
    expect(isEventNameValid('!a.b.c.d')).toBe(true);
    expect(isEventNameValid('!one.two')).toBe(true);
    expect(isEventNameValid('!one.two.three')).toBe(true);
    expect(isEventNameValid('!one.two.three.four')).toBe(true);

    expect(isEventNameValid('')).toBe(false);
    expect(isEventNameValid('a')).toBe(false);
    expect(isEventNameValid('.a')).toBe(false);
    expect(isEventNameValid('a.')).toBe(false);
    expect(isEventNameValid('.a.')).toBe(false);
    expect(isEventNameValid('!a')).toBe(false);
    expect(isEventNameValid('.!a')).toBe(false);
    expect(isEventNameValid('!.a')).toBe(false);
    expect(isEventNameValid('!a.')).toBe(false);
    expect(isEventNameValid('.!a.')).toBe(false);
    expect(isEventNameValid('one')).toBe(false);
    expect(isEventNameValid('one.')).toBe(false);
    expect(isEventNameValid('one.two.')).toBe(false);
  });

  it('should test isEventNameCached', () => {

    expect(isEventCached('!a')).toBe(false);
    expect(isEventCached('!a.b')).toBe(false);
    expect(isEventCached('!a.b.c')).toBe(false);
    expect(isEventCached('!one')).toBe(false);
    expect(isEventCached('!one.two')).toBe(false);
    expect(isEventCached('!one.two.three')).toBe(false);
    expect(isEventCached('!')).toBe(false);

    expect(isEventCached('Hello!')).toBe(true);
    expect(isEventCached('one.two.three!')).toBe(true);
    expect(isEventCached('one!two')).toBe(true);
    expect(isEventCached('')).toBe(true);
  });

  it('should be able to add to and listen to MFE events - uncached', () => {
    let eventsRespondedTo = 0;
    let eventsFired = 0;

    eventsFired++;
    dispatchMfeEvent('my-mfe', '!my.test.event', {testData: 'Hello World', eventsFired: eventsFired});

    expect(eventsRespondedTo).toBe(0);

    const removeMyTestEventListener = addMfeEventListener('!my.test.event', (mfeEvent: MfeEvent) => {
      eventsRespondedTo++;

      expect(mfeEvent.name).toBe('!my.test.event');
      expect(mfeEvent.context != null).toBe(true);
      expect(mfeEvent.context.testData).toBe('Hello World');
      //The eventsFired number is going to be one more than eventsResponded to because
      //there was a non-cached event fired before this listener was hooked up.
      expect(mfeEvent.context.eventsFired).toBe(eventsRespondedTo + 1);
    });

    expect(eventsRespondedTo).toBe(0);

    eventsFired++;
    dispatchMfeEvent('my-mfe', '!my.test.event', {testData: 'Hello World', eventsFired: eventsFired});
    expect(eventsRespondedTo).toBe(1);

    eventsFired++;
    dispatchMfeEvent('my-mfe', '!my.test.event', {testData: 'Hello World', eventsFired: eventsFired});
    expect(eventsRespondedTo).toBe(2);

    removeMyTestEventListener();
  });

  it('should be able to add to and listen to MFE events - cached', () => {
    let eventsFired = 0;
    let eventsRespondedTo = 0;

    eventsFired++;
    dispatchMfeEvent('my-mfe', 'my.test.event', {testData: 'Hello World', eventsFired: eventsFired});
    expect(eventsRespondedTo).toBe(0);

    const removeMyTestEventListener = addMfeEventListener('my.test.event', (mfeEvent: MfeEvent) => {
      eventsRespondedTo++;

      expect(mfeEvent.name).toBe('my.test.event');
      expect(mfeEvent.context != null).toBe(true);
      expect(mfeEvent.context.testData).toBe('Hello World');
      expect(mfeEvent.context.eventsFired).toBe(eventsRespondedTo);
    });

    expect(eventsRespondedTo).toBe(1);

    eventsFired++;
    dispatchMfeEvent('my-mfe', 'my.test.event', {testData: 'Hello World', eventsFired: eventsFired});
    expect(eventsRespondedTo).toBe(2);

    eventsFired++;
    dispatchMfeEvent('my-mfe', 'my.test.event', {testData: 'Hello World', eventsFired: eventsFired});
    expect(eventsRespondedTo).toBe(3);

    removeMyTestEventListener();
  });

  it('should be able to add to and listen to MFE events - ignoring cached events', () => {
    let eventsFired = 0;
    let eventsRespondedTo1 = 0;
    let eventsRespondedTo2 = 0;

    eventsFired++;
    dispatchMfeEvent('my-mfe', 'my.test.event', {testData: 'Hello World', eventsFired: eventsFired});
    expect(eventsRespondedTo1).toBe(0);

    const removeMyTestEventListener1 = addMfeEventListener('my.test.event', (mfeEvent: MfeEvent) => {
      eventsRespondedTo1++;

      expect(mfeEvent.name).toBe('my.test.event');
      expect(mfeEvent.context != null).toBe(true);
      expect(mfeEvent.context.testData).toBe('Hello World');
      expect(mfeEvent.context.eventsFired).toBe(eventsRespondedTo1 + 1);
    }, true);

    const removeMyTestEventListener2 = addMfeEventListener('my.test.event', (mfeEvent: MfeEvent) => {
      eventsRespondedTo2++;

      expect(mfeEvent.name).toBe('my.test.event');
      expect(mfeEvent.context != null).toBe(true);
      expect(mfeEvent.context.testData).toBe('Hello World');
      expect(mfeEvent.context.eventsFired).toBe(eventsRespondedTo2);
    });

    expect(eventsRespondedTo1).toBe(0);
    expect(eventsRespondedTo2).toBe(1);

    eventsFired++;
    dispatchMfeEvent('my-mfe', 'my.test.event', {testData: 'Hello World', eventsFired: eventsFired});
    expect(eventsRespondedTo1).toBe(1);
    expect(eventsRespondedTo2).toBe(2);

    eventsFired++;
    dispatchMfeEvent('my-mfe', 'my.test.event', {testData: 'Hello World', eventsFired: eventsFired});
    expect(eventsRespondedTo1).toBe(2);
    expect(eventsRespondedTo2).toBe(3);

    removeMyTestEventListener1();
    removeMyTestEventListener2();
  });
});